#!/usr/bin/env node
// Copies the Firebase Android config into the generated android/ project.
//
// Why this exists: `android/` is gitignored and fully regenerated by
// `npx cap add android` (docs/CAPACITOR.md), so anything placed inside it by
// hand is lost on the next regenerate — taking push notifications down with it.
// Same reason patch-ios-plist.sh exists for the iOS side. The durable copy
// lives at native/android/, and this puts it where Gradle looks.
//
// No Gradle edits are needed. Capacitor's own android/app/build.gradle already
// does the conditional:
//
//     def servicesJSON = file('google-services.json')
//     if (servicesJSON.text) { apply plugin: 'com.google.gms.google-services' }
//
// which is also why a missing file is not an error here: the build still
// succeeds, it just comes out without push. That is the supported state on any
// machine that has not been given the config.
//
// iOS deliberately does NOT get an equivalent. FCM reaches an iPhone via APNs,
// and the APNs key needs a PAID Apple Developer membership — so iOS stays on
// @capacitor/local-notifications (lib/notifications/syncReminders.ts), which
// fires with the app closed, no certificate, no membership. The client already
// picks per-device: registerPushDevice() answers `unavailable` on a build with
// no APNs, which leaves local scheduling in charge. Nothing branches on
// platform.

import { copyFileSync, existsSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const SOURCE = join(REPO_ROOT, 'native/android/google-services.json')
const DEST_DIR = join(REPO_ROOT, 'android/app')
const DEST = join(DEST_DIR, 'google-services.json')

function main() {
  if (!existsSync(SOURCE)) {
    // Not fatal, by design — everything except push works without it, and a
    // hard exit would block a teammate who only wants to run the app.
    console.warn('! No native/android/google-services.json — Android push will not register.')
    console.warn('  Everything else works. Get the file from the Firebase console')
    console.warn('  (Project settings → Your apps → Android) and put it there.')
    return
  }

  if (!existsSync(DEST_DIR)) {
    console.warn('! No android/ project yet — run `npx cap add android` first.')
    return
  }

  copyFileSync(SOURCE, DEST)
  console.log('✓ google-services.json → android/app/ (Android push enabled)')
}

main()
